function b64(s){ return Buffer.from(String(s || ''), 'utf8').toString('base64'); }
const body = $json.body ?? $json;
const pr = body.pull_request || {};
const repo = body.repository || {};
const action = body.action || 'manual';
const allowed = ['opened','synchronize','reopened','ready_for_review'].includes(action);
const owner = repo.owner?.login || repo.owner?.name || (repo.full_name || '').split('/')[0] || 'abdul4rehman215';
const repoName = repo.name || (repo.full_name || 'wazuh-genai-ci').split('/').pop();
const repoPath = body.repo_path || '/opt/detection-ci/wazuh-genai-ci';
return [{json:{
  action,
  pr_action_allowed: allowed,
  owner,
  repo_name: repoName,
  repo: repo.full_name || `${owner}/${repoName}`,
  pr_number: Number(pr.number || body.pr_number || 0),
  head_sha: pr.head?.sha || body.head_sha || 'local',
  branch: pr.head?.ref || body.branch || 'local',
  actor: body.sender?.login || pr.user?.login || body.actor || 'github',
  repo_path: repoPath,
  pr_url: pr.html_url || '',
  received_at: new Date().toISOString(),
  changed_files: [],
  changed_files_json: '[]',
  changed_files_b64: b64('[]')
}}];

function classify(path){
 const p=String(path||'').toLowerCase();
 if(p.includes('detections/wazuh') && p.endsWith('.xml')) return ['wazuh_content','high'];
 if(p.includes('detections/sigma')) return ['sigma','medium'];
 if(p.startsWith('metadata/')) return ['metadata','medium'];
 if(p.startsWith('schemas/')) return ['schema','high'];
 if(p.startsWith('policies/mcp')) return ['mcp_policy','high'];
 if(p.startsWith('policies/rag_memory')) return ['rag_memory_policy','high'];
 if(p.startsWith('policies/agentic')) return ['agentic_policy','high'];
 if(p.startsWith('mappings/')) return ['mapping','high'];
 if(p.startsWith('tests/')) return ['test_corpus','medium'];
 if(p.startsWith('data-tables/')) return ['datatable_schema','medium'];
 if(p.startsWith('docs/')) return ['documentation','low'];
 return ['other','low'];
}
const rows = ($json.changed_files || []).map((f,i)=>{ const path=f.filename || String(f); const [category,risk]=classify(path); return {change_id:`${$json.pr_number||0}-${i+1}`, file_path:path, change_status:f.status||'modified', category, risk_category:risk, validator_group:category, requires_review:risk==='high', notes:'classified by n8n Flow A2'}; });
const ciCategories = new Set(['wazuh_content','sigma','metadata','schema','mcp_policy','rag_memory_policy','agentic_policy','mapping','test_corpus','datatable_schema']);
const relevant = rows.filter(r=>ciCategories.has(r.category));
return [{json:{...$json, changed_file_rows:rows, relevant_change_count:relevant.length, relevant_ai_security_changes: relevant.length > 0, docs_only_change: rows.length > 0 && relevant.length === 0 && rows.every(r=>r.category === 'documentation')}}];

const now = new Date().toISOString();
const changedRows = $json.changed_file_rows || [];
const reason = changedRows.length ? 'Docs/non-security-only change; full AI-security CI not required' : 'No changed files returned by GitHub API; full AI-security CI not required';
return [{json:{...$json, ci_result:{
  ci_run_id:`a2-skip-${Date.now()}`,
  started_at:now,
  completed_at:now,
  duration_seconds:0,
  repo:$json.repo,
  pr_number:$json.pr_number,
  head_sha:$json.head_sha,
  actor:$json.actor,
  decision:'skip',
  status:'skipped',
  labels:['ai-security-ci-skip'],
  stage_results:[],
  changed_files: changedRows,
  relevant_change_count:0,
  summary: reason
}}}];

const ctx = $('Code_Classify_A2_Changed_Files').first().json;
const out = $json.stdout || $json.data || '';
const err = $json.stderr || '';
let result = null;
try { const start = String(out).indexOf('{'); result = JSON.parse(String(out).slice(start)); } catch(e) { result = null; }
if(!result){ result = {ci_run_id:`a2-error-${Date.now()}`, started_at:new Date().toISOString(), completed_at:new Date().toISOString(), duration_seconds:0, repo:ctx.repo, pr_number:ctx.pr_number, head_sha:ctx.head_sha, actor:ctx.actor, changed_files:ctx.changed_file_rows||[], stage_results:[], decision:'fail', status:'failed', labels:['ai-security-ci-fail'], summary:'Flow A2 local CI command did not return parseable JSON', command_error:String(err).slice(0,2000)}; }
return [{json:{...ctx, ci_result: result, command_stdout: String(out).slice(-6000), command_stderr: String(err).slice(-2000)}}];

const r = $json.ci_result || {};
const stages = r.stage_results || [];
const passed = stages.filter(s=>s.passed).length;
const failed = stages.length - passed;
const labels = (r.labels || []).join(',');
const stageLines = stages.map(s=>`- ${s.passed ? 'PASS' : 'FAIL'} ${s.stage_name}: ${s.summary || s.status}`).join('\n');
const diag = r.command_error || r.fix_hint || $json.command_stderr || '';
const diagBlock = diag ? ['','### Diagnostics', '```', String(diag).slice(0,3500), '```'].join('\n') : '';
const hintBlock = r.fix_hint ? ['','### Fix hint', String(r.fix_hint).slice(0,1000)].join('\n') : '';
const body = [
  `## Flow A2 AI Security Content CI`, '',
  `Decision: **${String(r.decision || '').toUpperCase()}**`,
  `Repo: ${r.repo || $json.repo}`,
  `PR: ${r.pr_number || $json.pr_number}`,
  `Commit: ${r.head_sha || $json.head_sha}`,
  `Stages: ${passed}/${stages.length} passed, ${failed} failed`,
  `Labels: ${labels}`, '',
  `### Stage results`, stageLines || 'No stages',
  diagBlock,
  hintBlock,
  '', `This workflow validates only. Deployment is handled by Phase 8 Flow B2.`
].join('\n');
const slack = [
  `*Flow A2 AI Security Content CI*`,
  `*Decision:* ${(r.decision || 'unknown').toUpperCase()}`,
  `*Repo/PR:* ${r.repo || $json.repo} #${r.pr_number || $json.pr_number}`,
  `*Commit:* ${r.head_sha || $json.head_sha}`,
  `*Stages:* ${passed}/${stages.length} passed, ${failed} failed`,
  `*Labels:* ${labels || 'n/a'}`,
  `*Summary:* ${r.summary || 'n/a'}`,
  r.fix_hint ? `*Fix hint:* ${r.fix_hint}` : ''
].filter(Boolean).join('\n');
return [{json:{...$json, github_comment_body:body, slack_text:slack, labels_csv: labels}}];

const base = $('Code_Build_A2_CI_Report').first().json;
const slack = $json || {};
const r = base.ci_result || {};
const stages = r.stage_results || [];
const runRow = {
 ci_run_id:r.ci_run_id, started_at:r.started_at, completed_at:r.completed_at, repo:r.repo||base.repo, branch:base.branch||'', pr_number:Number(r.pr_number||base.pr_number||0), head_sha:r.head_sha||base.head_sha, actor:r.actor||base.actor,
 changed_file_count:(r.changed_files||[]).length, relevant_change_count:Number(r.relevant_change_count||base.relevant_change_count||0), stages_total:stages.length, stages_passed:stages.filter(s=>s.passed).length, stages_failed:stages.filter(s=>!s.passed).length,
 decision:r.decision, status:r.status, labels_csv:(r.labels||[]).join(','), github_comment_status:'github_comment_created', slack_notified:!!(slack.channel || slack.ts || slack.message), duration_seconds:Number(r.duration_seconds||0), error:r.command_error||'', raw_result_json:JSON.stringify(r).slice(0,12000)
};
const changedRows = (r.changed_files || base.changed_file_rows || []).map((row,i)=>({...row, change_id: row.change_id || `${r.ci_run_id}-file-${i+1}`, ci_run_id:r.ci_run_id}));
const stageRows = stages.map((s,i)=>({ stage_result_id:`${r.ci_run_id}-${s.stage_name || i}`, ci_run_id:r.ci_run_id, stage_name:s.stage_name || `stage_${i}`, category:s.stage_name || '', status:s.status, passed:!!s.passed, duration_seconds:Number(s.duration_seconds||0), files_checked:Number(s.files_checked||0), findings_count:Number(s.findings_count||0), summary:s.summary||'', details_json:JSON.stringify(s.details||{}).slice(0,8000)}));
const replay = stages.find(s=>s.stage_name === 'v2_replay_harness') || {};
const parsed = replay.details?.parsed || {};
const regressionRow = { regression_run_id:`${r.ci_run_id}-replay`, started_at:r.started_at, completed_at:r.completed_at, trigger_type:'pr', repo:r.repo||base.repo, head_sha:r.head_sha||base.head_sha, corpus_version:parsed.corpus_version || 'v2-phase7-local-static', total_tests:Number(parsed.total_tests||0), positive_total:Number(parsed.positive_total||0), positive_passed:Number(parsed.positive_passed||0), positive_failed:Number(parsed.positive_failed||0), negative_total:Number(parsed.negative_total||0), negative_passed:Number(parsed.negative_passed||0), negative_failed:Number(parsed.negative_failed||0), expected_rule_mismatches:JSON.stringify(parsed.expected_rule_mismatches||[]), alert_volume_before:0, alert_volume_after:0, regression_status:replay.passed?'pass':'fail', github_issue_url:'', slack_notified:!!(slack.channel || slack.ts || slack.message), notes:replay.summary||'' };
return [{json:{...base, slack_response:slack, ci_run_row:runRow, changed_file_rows:changedRows, stage_result_rows:stageRows, regression_row:regressionRow}}];

function b64(s){ return Buffer.from(String(s || ''), 'utf8').toString('base64'); }
const ctx = $('Code_Extract_A2_Context').first().json;
const items = $input.all().map(i => i.json);
let files = [];
if (items.length === 1 && Array.isArray(items[0])) files = items[0]; else files = items;
files = files.filter(Boolean).map(f => ({
  filename: f.filename || f.name || String(f),
  status: f.status || 'modified',
  additions: Number(f.additions || 0),
  deletions: Number(f.deletions || 0),
  changes: Number(f.changes || 0)
}));
const filesJson = JSON.stringify(files);
return [{ json: { ...ctx, changed_files: files, changed_files_json: filesJson, changed_files_b64: b64(filesJson) } }];
